import{_ as o,o as e,c as t,a5 as r}from"./chunks/framework.BEZBAInb.js";const u=JSON.parse('{"title":"安裝 Konado","description":"","frontmatter":{"title":"安裝 Konado","order":1},"headers":[],"relativePath":"tc/2.4/tutorial/install.md","filePath":"tc/2.4/tutorial/install.md","lastUpdated":1788455378000}'),l={name:"tc/2.4/tutorial/install.md"};function i(n,a,d,s,h,c){return e(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="安裝-konado" tabindex="-1">安裝 Konado <a class="header-anchor" href="#安裝-konado" aria-label="Permalink to &quot;安裝 Konado&quot;">​</a></h1><h2 id="依賴環境" tabindex="-1">依賴環境 <a class="header-anchor" href="#依賴環境" aria-label="Permalink to &quot;依賴環境&quot;">​</a></h2><p>需要使用 <strong>Godot 4.6 或更高版本</strong></p><p>以下 Godot 版本均經過開發者測試，可以正常使用：</p><ul><li>4.6</li><li>4.5.1</li><li>4.5</li></ul><h3 id="插件下載" tabindex="-1">插件下載 <a class="header-anchor" href="#插件下載" aria-label="Permalink to &quot;插件下載&quot;">​</a></h3><h4 id="穩定版-推薦" tabindex="-1">穩定版（推薦） <a class="header-anchor" href="#穩定版-推薦" aria-label="Permalink to &quot;穩定版（推薦）&quot;">​</a></h4><p>請前往 <a href="https://github.com/godothub/konado/releases/latest" target="_blank" rel="noreferrer">Konado 最新版本頁面</a> 下載最新穩定版插件 ZIP 壓縮包。穩定版經過充分驗證，穩定性和可靠性更有保障，是生產環境的首選。</p><p>為提升中國大陸地區使用者的下載體驗，推薦使用此最佳化連結取得資源：<a href="https://atomgit.com/godothub/konado/releases" target="_blank" rel="noreferrer">Release 連結</a>，此連結可有效改善下載速度。</p><h4 id="每日構建版-嘗鮮版" tabindex="-1">每日構建版（嘗鮮版） <a class="header-anchor" href="#每日構建版-嘗鮮版" aria-label="Permalink to &quot;每日構建版（嘗鮮版）&quot;">​</a></h4><p>我們同步提供每日構建版。如需體驗最新開發特性，可前往 <a href="https://github.com/godothub/konado/releases/" target="_blank" rel="noreferrer">Konado 全版本頁面</a>，尋找標題標註有 <code>Konado Daily Build</code> 的版本下載。</p><p>如果你是開發人員，並且希望體驗最新開發特性，可以下載每日構建版，並將使用過程中遇到的問題回饋到 Issues 中。</p><blockquote><p>Caution：每日構建版僅用於體驗最新開發特性，由於包含未經完整測試的新功能，可能會存在未修復的 Bug，<strong>請不要用於生產環境</strong>，請根據實際需求謹慎選擇。</p></blockquote><h2 id="安裝步驟" tabindex="-1">安裝步驟 <a class="header-anchor" href="#安裝步驟" aria-label="Permalink to &quot;安裝步驟&quot;">​</a></h2><ol><li>在 Godot 工程目錄新建插件資料夾 <code>addons</code></li><li>下載 release 的插件 zip 包</li><li>解壓到 <code>addons</code> 目錄下</li><li>在 Godot 專案設定中啟用插件，並重新載入目前專案</li></ol><blockquote><p>Tip: 首次安裝並啟用插件時可能會出現一些報錯，可以忽略，重新載入專案即可。</p></blockquote><h2 id="開發團隊寄語" tabindex="-1">開發團隊寄語 <a class="header-anchor" href="#開發團隊寄語" aria-label="Permalink to &quot;開發團隊寄語&quot;">​</a></h2><p>你已成功安裝 Konado 插件。在正式開始創作前，想與你分享一段寄語：</p><blockquote><p>「 對於任何行業來說，想像力配上一絲智慧，都是無堅不摧的武器。」</p><p>—— 菲利普·K·迪克（Philip K. Dick）<br> 《少數派報告》（<em>Minority Report</em>，1956）</p></blockquote><p>願你始終保有想像力與精益求精的態度，在創作之路上探索更多可能。</p>',20)])])}const b=o(l,[["render",i]]);export{u as __pageData,b as default};
